payload.arguments:
{"description":"Test dec sweep vs snake","cmd":"cd candidates && for dec in 1200 1333 1500 1800 2000 2200 2400 2667 2700 2800 3000 3200 3600 4000; do
r=$(pmars -b -r 100 -f pclear_$dec.red ../warriors/snake.red 2>&1 | grep Results);
echo "dec=$dec snake: $r";
done"}

{"description":"Test promising dec values against all opponents","cmd":"cd candidates && for dec in 1500 2000 2667 2800; do
echo "===== dec=$dec ====="
for o in stone paper vampire snake g2-clear; do
r=$(pmars -b -r 100 -f pclear_$dec.red ../warriors/$o.red 2>&1 | grep Results);
echo "  $o: $r";
done
done"}

{"description":"Test more dec values against all opponents","cmd":"cd candidates && for dec in 2200 2400 2500 2600 2650 3000 3200 3400; do
echo "===== dec=$dec ====="
for o in stone paper vampire snake g2-clear; do
r=$(pmars -b -r 100 -f pclear_$dec.red ../warriors/$o.red 2>&1 | grep Results);
echo "  $o: $r";
done
done"}

{"description":"Confirm nmov1 results","cmd":"cd candidates && for o in stone paper vampire snake g2-clear; do
r=$(pmars -b -r 100 -f pmovs_1.red ../warriors/$o.red 2>&1 | grep Results);
echo "pmovs_1 vs $o: $r";
done"}

{"description":"Verify final warrior against all opponents","cmd":"for o in stone paper vampire snake g2-clear; do
echo "=== my_warrior.red vs $o ===";
pmars -b -r 100 -f my_warrior.red warriors/$o.red 2>&1 | grep -E 'Results|scores';
done"}

{"description":"Confirm deterministic repeatability","cmd":"for i in 1 2 3; do
echo "run $i:";
for o in stone paper vampire snake g2-clear; do
r=$(pmars -b -r 100 -f my_warrior.red warriors/$o.red 2>&1 | grep Results);
echo "  $o: $r";
done
done"}
